  if (percent === undefined) return COLOR.slateLight;
  if (percent >= 90) return COLOR.red;
  if (percent >= 70) return COLOR.amber;
  return COLOR.green;
}

function statusColor(text: string): string {
  const normalized = stripAnsi(text).toLowerCase();
  if (/error|fail|missing|conflict|unavailable|blocked/.test(normalized)) return COLOR.red;
  if (/warn|duplicate|pending|dirty/.test(normalized)) return COLOR.amber;
  if (/active|running|enabled|ready|ok|success|✓/.test(normalized)) return COLOR.green;
  return COLOR.slate;
}

