import { basename } from "node:path";
import process from "node:process";
import type {
  ExtensionAPI,
  ExtensionContext,
  ReadonlyFooterDataProvider,
} from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

type ThinkingLevel = ReturnType<ExtensionAPI["getThinkingLevel"]>;

interface RuntimeState {
  turnCount: number;
  activeTools: Map<string, number>;
  isStreaming: boolean;
  thinkingLevel: ThinkingLevel;
  lastCompletedTool?: string;
  requestRender?: () => void;
}

interface TokenTotals {
  input: number;
  output: number;
  cost: number;
}

interface BadgeSegment {
  key: string;
  label: string;
  value: string;
  bg: string;
  labelFg?: string;
  valueFg?: string;
  valueBg?: string;
  priority: 1 | 2 | 3 | 4;
}

const FOOTER_KEY = "pi-status";
const COLOR = {
  text: "#f8fafc",
  muted: "#cbd5e1",
  black: "#020617",
  surface: "#111827",
  surfaceSoft: "#1f2937",
  slate: "#334155",
  slateLight: "#475569",
  blue: "#2563eb",
  cyan: "#06b6d4",
  green: "#16a34a",
  amber: "#f59e0b",
  red: "#dc2626",
  violet: "#7c3aed",
  magenta: "#c026d3",
} as const;

export default function piStatus(pi: ExtensionAPI): void {
  let enabled = process.env.PI_STATUS !== "0";
  const runtime: RuntimeState = {
    turnCount: 0,
    activeTools: new Map(),
    isStreaming: false,
    thinkingLevel: "off",
  };

  const refresh = () => runtime.requestRender?.();

  const installFooter = (ctx: ExtensionContext) => {
    if (ctx.mode !== "tui") return;

    ctx.ui.setStatus(FOOTER_KEY, undefined);

    if (!enabled) {
      ctx.ui.setFooter(undefined);
      runtime.requestRender = undefined;
      return;
    }

    ctx.ui.setFooter((tui, _theme, footerData) => {
      runtime.requestRender = () => tui.requestRender();
      const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());
      const clock = setInterval(() => tui.requestRender(), 60_000);

      return {
        dispose() {
          unsubscribeBranch();
          clearInterval(clock);
        },
        invalidate() {},
        render(width: number): string[] {
          const main = renderMainLine(width, ctx, footerData, runtime);
          const statuses = renderStatusLine(width, footerData);
          return statuses ? [main, statuses] : [main];
        },
      };
    });
  };

  pi.registerCommand("pi-status", {
    description: "Toggle the high-contrast Pi status footer. Usage: /pi-status [on|off|toggle]",
    handler: async (args, ctx) => {
      const action = args.trim().toLowerCase();
      if (action === "on") enabled = true;
      else if (action === "off") enabled = false;
      else enabled = !enabled;

      installFooter(ctx);
      ctx.ui.notify(`High-contrast status footer ${enabled ? "enabled" : "disabled"}`, "info");
    },
  });

  pi.on("session_start", (_event, ctx) => {
    runtime.thinkingLevel = pi.getThinkingLevel();
    installFooter(ctx);
  });

  pi.on("session_tree", (_event, ctx) => {
    installFooter(ctx);
    refresh();
  });

  pi.on("session_shutdown", (_event, ctx) => {
    if (ctx.mode === "tui") ctx.ui.setFooter(undefined);
    ctx.ui.setStatus(FOOTER_KEY, undefined);
    runtime.requestRender = undefined;
  });

  pi.on("model_select", () => refresh());

  pi.on("thinking_level_select", (event) => {
    runtime.thinkingLevel = event.level;
    refresh();
  });

  pi.on("agent_start", () => {
    runtime.isStreaming = true;
    refresh();
  });

  pi.on("agent_end", () => {
    runtime.isStreaming = false;
    refresh();
  });

  pi.on("turn_start", () => {
    runtime.turnCount += 1;
    runtime.isStreaming = true;
    refresh();
  });

  pi.on("turn_end", () => refresh());

  pi.on("tool_execution_start", (event) => {
    const count = runtime.activeTools.get(event.toolName) ?? 0;
    runtime.activeTools.set(event.toolName, count + 1);
    refresh();
  });

  pi.on("tool_execution_end", (event) => {
    const count = runtime.activeTools.get(event.toolName) ?? 0;
    if (count <= 1) runtime.activeTools.delete(event.toolName);
    else runtime.activeTools.set(event.toolName, count - 1);

    runtime.lastCompletedTool = event.toolName;
    refresh();
  });
}

function renderMainLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
  runtime: RuntimeState,
): string {
  if (width <= 0) return "";

  const left: BadgeSegment[] = [
    badge("brand", "π", "status", COLOR.cyan, 1, { labelFg: COLOR.black }),
    activitySegment(runtime),
    badge("model", "model", modelName(ctx), COLOR.blue, 1),
    badge("think", "think", runtime.thinkingLevel, thinkingColor(runtime.thinkingLevel), 3),
    badge("cwd", "dir", basename(ctx.cwd) || ctx.cwd, COLOR.slateLight, 2),
  ];

  const branch = footerData.getGitBranch();
  if (branch) left.push(badge("git", "git", shorten(branch, 24), COLOR.green, 2));

  const context = ctx.getContextUsage();
  const contextPercent = typeof context?.percent === "number" ? context.percent : undefined;
  const totals = getTokenTotals(ctx);

  const right: BadgeSegment[] = [
    badge("ctx", "ctx", contextPercent === undefined ? "?" : `${contextPercent.toFixed(0)}%`, contextColor(contextPercent), 1, {
      labelFg: contextPercent !== undefined && contextPercent < 90 ? COLOR.black : COLOR.text,
    }),
    badge("tokens", "tok", `↑${formatCount(totals.input)} ↓${formatCount(totals.output)}`, COLOR.slate, 3),
    badge("cost", "cost", `$${formatCost(totals.cost)}`, COLOR.violet, 4),
    badge("turn", "turn", `#${runtime.turnCount}`, COLOR.slateLight, 4),
    badge("time", "time", formatTime(), COLOR.slateLight, 4),
  ];

  return fitTwoSidedLine(width, left, right);
}

function activitySegment(runtime: RuntimeState): BadgeSegment {
  const active = [...runtime.activeTools.entries()];
  if (active.length > 0) {
    const [name, count] = active[0] ?? ["tool", 1];
    const suffix = count > 1 ? `×${count}` : active.length > 1 ? `+${active.length - 1}` : "";
    return badge("activity", "run", `${shorten(name, 18)}${suffix}`, COLOR.amber, 1, {
      labelFg: COLOR.black,
      valueFg: COLOR.text,
    });
  }

  if (runtime.isStreaming) {
    return badge("activity", "run", "thinking", COLOR.magenta, 1);
  }

  if (runtime.lastCompletedTool) {
    return badge("activity", "done", shorten(runtime.lastCompletedTool, 18), COLOR.green, 2, {
      labelFg: COLOR.black,
    });
  }

  return badge("activity", "idle", "ready", COLOR.green, 1, { labelFg: COLOR.black });
}

function badge(
  key: string,
  label: string,
  value: string,
  bg: string,
  priority: 1 | 2 | 3 | 4,
  options: Partial<Pick<BadgeSegment, "labelFg" | "valueFg" | "valueBg">> = {},
): BadgeSegment {
  return {
    key,
    label: label.toUpperCase(),
    value,
    bg,
    priority,
    labelFg: options.labelFg,
    valueFg: options.valueFg,
    valueBg: options.valueBg,
  };
}

function fitTwoSidedLine(width: number, left: BadgeSegment[], right: BadgeSegment[]): string {
  for (let maxPriority = 4; maxPriority >= 1; maxPriority -= 1) {
    const leftText = renderBadges(left.filter((segment) => segment.priority <= maxPriority));
    const rightText = renderBadges(right.filter((segment) => segment.priority <= maxPriority));
    const leftWidth = visibleWidth(leftText);
    const rightWidth = visibleWidth(rightText);

    if (leftWidth + rightWidth + 1 <= width) {
      const padding = " ".repeat(Math.max(1, width - leftWidth - rightWidth));
      return truncateToWidth(leftText + padding + rightText, width, "");
    }

    if (rightWidth === 0 && leftWidth <= width) return truncateToWidth(leftText, width, "");
  }

  return truncateToWidth(renderBadges(left.slice(0, 2)), width, "");
}

function renderBadges(segments: BadgeSegment[]): string {
  return segments.map(renderBadge).join(" ");
}

function renderBadge(segment: BadgeSegment): string {
  const label = ansi(` ${segment.label} `, {
    fg: segment.labelFg ?? COLOR.text,
    bg: segment.bg,
    bold: true,
  });
  const value = ansi(` ${segment.value} `, {
    fg: segment.valueFg ?? COLOR.text,
    bg: segment.valueBg ?? COLOR.surface,
  });
  return label + value;
}

function renderStatusLine(width: number, footerData: ReadonlyFooterDataProvider): string | undefined {
  if (width <= 0) return undefined;

  const statuses = [...footerData.getExtensionStatuses().entries()]
    .filter(([key, value]) => key !== FOOTER_KEY && stripAnsi(value).trim().length > 0)
    .slice(0, 5)
    .map(([key, value]) => renderExtensionStatus(key, value));

  if (statuses.length === 0) return undefined;

  const prefix = ansi(" EXT ", { fg: COLOR.text, bg: COLOR.violet, bold: true });
  let line = prefix;

  for (const status of statuses) {
    const candidate = `${line} ${status}`;
    if (visibleWidth(candidate) > width) break;
    line = candidate;
  }

  return truncateToWidth(line, width, "");
}

function renderExtensionStatus(key: string, value: string): string {
  const cleanKey = simplifyStatusText(key).toUpperCase();
  const cleanValue = simplifyStatusText(value.replace(new RegExp(`^${escapeRegExp(key)}\\s*:\\s*`, "iu"), ""));
  const bg = statusColor(`${key} ${value}`);
  const fg = bg === COLOR.amber || bg === COLOR.green || bg === COLOR.cyan ? COLOR.black : COLOR.text;
  return ansi(` ${shorten(cleanKey, 10)} ${shorten(cleanValue, 28)} `, { fg, bg });
}

function modelName(ctx: ExtensionContext): string {
  const model = ctx.model as { id?: string; provider?: string; name?: string } | undefined;
  const raw = model?.id ?? model?.name ?? "no model";
  return shortenModel(raw);
}

