  return shorten(
    model
      .replace(/^claude-/, "")
      .replace(/^gpt-/, "gpt ")
      .replace(/-20\d{6}$/, "")
      .replace(/-latest$/, "")
      .replace(/-(instruct|preview|thinking)$/i, ""),
    30,
