edits.oldText:
function contextSnapshot(ctx: ExtensionContext): { label: string; color: string } {
  const usage = ctx.getContextUsage();
  const percent = typeof usage?.percent === "number" ? usage.percent : undefined;
  if (percent === undefined) return { label: "░░░░░░ ?", color: COLOR.panelSoft };

  const clamped = Math.max(0, Math.min(100, percent));
  const cells = 6;
  const filled = Math.round((clamped / 100) * cells);
  const bar = `${"█".repeat(filled)}${"░".repeat(cells - filled)}`;
  return { label: `${bar} ${clamped.toFixed(0)}%`, color: contextColor(clamped) };
}

function contextColor(percent: number): string {
  if (percent >= 90) return COLOR.contextFull;
  if (percent >= 70) return COLOR.contextWarn;
  return COLOR.contextGood;
}

edits.newText:
function contextSnapshot(ctx: ExtensionContext): { label: string; color: string } {
  const usage = ctx.getContextUsage();
  const percent = typeof usage?.percent === "number" ? usage.percent : undefined;
  if (percent === undefined) return { label: "?", color: COLOR.contextTransparent };

  const clamped = Math.max(0, Math.min(100, percent));
  return { label: `${clamped.toFixed(0)}%`, color: contextColor(clamped) };
}

function contextColor(percent: number): string {
  if (percent < 10) return COLOR.contextTransparent;
  if (percent < 20) return COLOR.contextLightGreen;
  if (percent < 30) return COLOR.contextGreen;
  if (percent < 40) return COLOR.contextYellow;
  if (percent < 50) return COLOR.contextOrange;
  return COLOR.contextRed;
}

